import * as React from 'react';
import { cleanup, render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { act } from 'react';
import { Slot } from './slot';
import { describe, it, expect } from 'vitest';

describe('debug ref behavior (unfixed Slot)', () => {
  it('counts ref invocations', async () => {
    const CountingInput = () => {
      const [value, setValue] = React.useState('');
      const [refCalls, setRefCalls] = React.useState(0);
      const countRef = React.useCallback((_node: HTMLInputElement | null) => {
        setRefCalls((count) => count + 1);
      }, []);

      return (
        <Slot onChange={(event) => setValue(event.target.value)}>
          <input data-ref-calls={refCalls} ref={countRef} value={value} />
        </Slot>
      );
    };

    const { container } = render(<CountingInput />);
    await act(async () => {});
    console.log('calls after mount:', container.querySelector('input')?.getAttribute('data-ref-calls'));
    await userEvent.type(screen.getByRole('textbox'), 'f');
    await act(async () => {});
    console.log('calls after type f:', container.querySelector('input')?.getAttribute('data-ref-calls'));
    await userEvent.type(screen.getByRole('textbox'), 'o');
    await act(async () => {});
    console.log('calls after type fo:', container.querySelector('input')?.getAttribute('data-ref-calls'));
    await act(async () => {});
    console.log(
      'calls final:',
      container.querySelector('input')?.getAttribute('data-ref-calls'),
      'value:',
      container.querySelector('input')?.value,
    );
    expect(true).toBe(true);
  });
});
